//! Two-unit joint golden (1.8.0): `fixtures/golden/joint_small.*` from the
//! packaged SciPy reference `eltq.reference_multiunit`, regenerated by
//! `uv run python fixtures/generate_fixtures.py`.

use std::path::PathBuf;

use eltq_core::{JointConfig, UnitSpec, ZRule, joint_two_units};

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures")
}

#[test]
fn joint_small_golden() {
    let meta_json: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(fixtures_dir().join("golden/joint_small.meta.json")).unwrap(),
    )
    .unwrap();
    let params = &meta_json["params"];
    let unit = |i: usize| {
        let u = params["units"][i].as_array().unwrap();
        UnitSpec {
            mean_loss: u[0].as_f64().unwrap(),
            sd_indep: u[1].as_f64().unwrap(),
            sd_corr: u[2].as_f64().unwrap(),
            max_loss: u[3].as_f64().unwrap(),
        }
    };
    let mut config = JointConfig::new(
        params["bucket_size"].as_f64().unwrap(),
        params["n1"].as_u64().unwrap() as usize,
        params["n2"].as_u64().unwrap() as usize,
    );
    config.z_nodes = params["z_nodes"].as_u64().unwrap() as usize;
    config.z_rule = ZRule::parse(params["z_rule"].as_str().unwrap()).unwrap();
    let result = joint_two_units([unit(0), unit(1)], &config).unwrap();

    let text = std::fs::read_to_string(fixtures_dir().join("golden/joint_small.pmf.csv")).unwrap();
    let mut golden = Vec::with_capacity(result.pmf.len());
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        for cell in line.split(',') {
            golden.push(cell.trim().parse::<f64>().unwrap());
        }
    }
    assert_eq!(golden.len(), result.n1 * result.n2);
    let mut worst = (0.0_f64, 0usize);
    for (i, (&g, &w)) in result.pmf.iter().zip(&golden).enumerate() {
        let tolerance = 1e-12 + 1e-9 * w.abs();
        let diff = (g - w).abs();
        if diff / tolerance > worst.0 {
            worst = (diff / tolerance, i);
        }
        assert!(diff <= tolerance, "pmf[{i}]: got {g}, want {w} (diff {diff})");
    }
    eprintln!("joint golden: worst diff/tolerance {} at cell {}", worst.0, worst.1);

    let meta = &result.meta;
    let rel = |got: f64, want: f64| (got - want).abs() / want.abs().max(f64::MIN_POSITIVE);
    assert!(rel(meta.total_mass, meta_json["total_mass"].as_f64().unwrap()) < 1e-12);
    assert!(rel(meta.grid_correlation, meta_json["grid_correlation"].as_f64().unwrap()) < 1e-9);
    for i in 0..2 {
        assert!(rel(meta.alpha[i], meta_json["alpha"][i].as_f64().unwrap()) < 1e-14);
        assert!(rel(meta.grid_mean[i], meta_json["grid_mean"][i].as_f64().unwrap()) < 1e-9);
        assert!(rel(meta.grid_sd[i], meta_json["grid_sd"][i].as_f64().unwrap()) < 1e-9);
    }
}
